180		first.Commitments = first.Commitments[:0]
181	
182		// 同时刻取回的另一份结果保持真实内容。
183		assertJustPastView(t, second, deadline, commitExpiry)
184	
185		// 重新查询仍是事实：过保、承诺有效 4/1/3。
186		again, err := s.RequestView("r1", justPast)
187		if err != nil {
188			t.Fatalf("re-query view: %v", err)
189		}
190		assertJustPastView(t, again, deadline, commitExpiry)
191	
192		// 直接查询资格仍只显示过保，登记依据不变。
193		e, err := s.Evaluate("r1", justPast)
194		if err != nil {
195			t.Fatalf("evaluate after mutation: %v", err)
196		}
197		assertExpiredOnlyBasis(t, e, t0, deadline)
198	
199		// 库存账目不把编辑当真实使用或取消：9/3/6。
200		st, err := s.PartStatus("part1", justPast)
201		if err != nil {
202			t.Fatalf("part status after mutation: %v", err)
203		}
204		if st.PhysicalRemaining != 9 || st.ActiveOccupied != 3 || st.Committable != 6 {
205			t.Fatalf("stock after mutation = %d/%d/%d, want 9/3/6",
206				st.PhysicalRemaining, st.ActiveOccupied, st.Committable)
207		}
208		d, ok := detailByID(st, "c1")
209		if !ok {
210			t.Fatalf("part details lost c1: %+v", st.Details)
211		}
212		assertC1Snapshot(t, d, 1, 3, CommitmentActive, commitExpiry)
213	
214		// 仓库记录本身不被改写。
215		c, err := s.Commitment("c1")
216		if err != nil {
217			t.Fatalf("commitment c1: %v", err)
218		}
219		if c.RequestID != "r1" || c.PartID != "part1" || c.Quantity != 4 ||
220			c.Used != 1 || c.Canceled || c.Expired || !c.Expiry.Equal(commitExpiry) {
221			t.Fatalf("stored commitment altered: %+v", c)
222		}
223		p, err := s.Product("p1")
224		if err != nil {
225			t.Fatalf("product p1: %v", err)
226		}
227		if !p.PurchaseTime.Equal(t0) || p.WarrantyDays != 30 {
228			t.Fatalf("stored product terms altered: %+v", p)
229		}
230		if _, excluded := p.ExcludedCodes["NOISE"]; excluded {
231			t.Fatalf("NOISE became excluded through view mutation")
232		}
233	}
234	
235	// TestRequestViewSnapshotsDoNotTrackLaterRealOperations 已取回的结果不随之后
236	// 的真实使用变化：承诺到期前再成功使用一件后，新查询显示已用两件、未用两件，
237	// 库存变为实物八件、有效占用两件、可承诺六件；此前取回（未经调用方修改）的
238	// 结果仍保留已用一件、未用三件。保修截止前取得的合格结果也不会被后来的过保
239	// 查询改写。
240	func TestRequestViewSnapshotsDoNotTrackLaterRealOperations(t *testing.T) {
241		s, deadline, commitExpiry, justPast := rvSnapSetup(t)
242	
243		// 保修截止前取得的合格结果：无拒绝原因，依据相同，承诺同样定格在 4/1/3。
244		inWindow := t0.Add(20 * day)
245		eligibleView, err := s.RequestView("r1", inWindow)
246		if err != nil {
247			t.Fatalf("view in warranty: %v", err)
248		}
249		if !eligibleView.Eligibility.Eligible || eligibleView.Eligibility.Excluded ||
250			len(eligibleView.Eligibility.Reasons) != 0 {
251			t.Fatalf("in-window eligibility = %+v, want eligible with no reasons",
252				eligibleView.Eligibility)
253		}
254		if !eligibleView.Eligibility.PurchaseTime.Equal(t0) ||
255			eligibleView.Eligibility.WarrantyDays != 30 ||
256			!eligibleView.Eligibility.WarrantyExpiry.Equal(deadline) {
257			t.Fatalf("in-window basis altered: %+v", eligibleView.Eligibility)
258		}
259		if len(eligibleView.Commitments) != 1 {
260			t.Fatalf("in-window commitments = %+v, want one c1", eligibleView.Commitments)
261		}
262		assertC1Snapshot(t, eligibleView.Commitments[0], 1, 3, CommitmentActive, commitExpiry)
263	
264		// 刚过保、承诺未到期时取得的结果：资格只有过保，承诺仍 4/1/3。
265		staleView, err := s.RequestView("r1", justPast)
266		if err != nil {
267			t.Fatalf("view just past warranty: %v", err)
268		}
269		assertJustPastView(t, staleView, deadline, commitExpiry)
270	
271		// 承诺到期前再真实使用一件。
272		secondUseAt := t0.Add(40 * day)
273		if _, err := s.Use("u2", "c1", 1, secondUseAt); err != nil {
274			t.Fatalf("second real use: %v", err)
275		}
276	
277		// 新查询反映真实变化：已用两件、未用两件，承诺在到期时刻前仍有效。
278		fresh, err := s.RequestView("r1", secondUseAt)
279		if err != nil {
280			t.Fatalf("view after second use: %v", err)
281		}
282		assertExpiredOnlyBasis(t, fresh.Eligibility, t0, deadline)
283		if len(fresh.Commitments) != 1 {
284			t.Fatalf("fresh commitments = %+v, want one c1", fresh.Commitments)
285		}
286		assertC1Snapshot(t, fresh.Commitments[0], 2, 2, CommitmentActive, commitExpiry)
287	
288		// 库存：实物八件、有效占用两件、可承诺六件。
289		st, err := s.PartStatus("part1", secondUseAt)
290		if err != nil {
291			t.Fatalf("part status after second use: %v", err)
292		}
293		if st.PhysicalRemaining != 8 || st.ActiveOccupied != 2 || st.Committable != 6 {
294			t.Fatalf("stock after second use = %d/%d/%d, want 8/2/6",
295				st.PhysicalRemaining, st.ActiveOccupied, st.Committable)
296		}
297	
298		// 此前未经修改的两份结果不被真实使用回写。
299		if len(staleView.Commitments) != 1 {
300			t.Fatalf("stale view commitments changed: %+v", staleView.Commitments)
301		}
302		assertC1Snapshot(t, staleView.Commitments[0], 1, 3, CommitmentActive, commitExpiry)
303		assertExpiredOnlyBasis(t, staleView.Eligibility, t0, deadline)
304		if len(eligibleView.Commitments) != 1 {
305			t.Fatalf("eligible view commitments changed: %+v", eligibleView.Commitments)
306		}
307		assertC1Snapshot(t, eligibleView.Commitments[0], 1, 3, CommitmentActive, commitExpiry)
308		if !eligibleView.Eligibility.Eligible || len(eligibleView.Eligibility.Reasons) != 0 {
309			t.Fatalf("earlier eligible result rewritten by later expired query: %+v",
310				eligibleView.Eligibility)
311		}
312	}
313	
314	// TestRequestViewEmptyCommitmentsStaysEmptyUntilLaterReserve 尚无承诺的已知
315	// 请求：原查询返回实际资格与空明细；之后正常预留成功，只在新查询中出现承诺，
316	// 不向已经取回的空结果补入记录。
317	func TestRequestViewEmptyCommitmentsStaysEmptyUntilLaterReserve(t *testing.T) {
318		s := NewStore()
319		if err := s.RegisterProduct("p1", t0, 30, []string{"FAULTX"}); err != nil {
320			t.Fatalf("register product: %v", err)
321		}
322		if err := s.RegisterPart("part1", 10); err != nil {
323			t.Fatalf("register part: %v", err)
324		}
325		if err := s.SubmitRequest("rEmpty", "p1", "NOISE"); err != nil {
326			t.Fatalf("submit request: %v", err)
327		}
328	
329		inWindow := t0.Add(5 * day)
330		before, err := s.RequestView("rEmpty", inWindow)
331		if err != nil {
332			t.Fatalf("view before reserve: %v", err)
333		}
334		if !before.Eligibility.Eligible || before.Eligibility.Excluded ||
335			len(before.Eligibility.Reasons) != 0 {
336			t.Fatalf("eligibility before reserve = %+v, want eligible with no reasons",
337				before.Eligibility)
338		}
339		if len(before.Commitments) != 0 {
340			t.Fatalf("commitments before reserve = %+v, want empty", before.Commitments)
341		}
342	
343		// 之后正常预留成功。
344		commitExpiry := t0.Add(50 * day)
345		if _, err := s.Reserve("c-later", "rEmpty", "part1", 2, commitExpiry, t0.Add(6*day)); err != nil {
346			t.Fatalf("later reserve: %v", err)
347		}
348	
349		// 新查询出现承诺：合格、明细一条，原数量两件、未使用、有效。
350		after, err := s.RequestView("rEmpty", t0.Add(7*day))
351		if err != nil {
352			t.Fatalf("view after reserve: %v", err)
353		}
354		if !after.Eligibility.Eligible || len(after.Eligibility.Reasons) != 0 {
355			t.Fatalf("eligibility after reserve = %+v, want eligible with no reasons",
356				after.Eligibility)
357		}
358		if len(after.Commitments) != 1 {
359			t.Fatalf("commitments after reserve = %+v, want exactly one", after.Commitments)
360		}
361		got := after.Commitments[0]
362		want := CommitmentDetail{
363			CommitmentID:      "c-later",
364			RequestID:         "rEmpty",
365			PartID:            "part1",
366			OriginalQuantity:  2,
367			UsedQuantity:      0,
368			RemainingQuantity: 2,
369			Expiry:            commitExpiry,
370			Status:            CommitmentActive,
371		}
372		if got != want {
373			t.Fatalf("later commitment detail = %+v, want %+v", got, want)
374		}
375	
376		// 先前取回的空结果不被补入记录，资格也保持当时的合格事实。
377		if len(before.Commitments) != 0 {
378			t.Fatalf("earlier empty view gained commitments: %+v", before.Commitments)
379		}
380		if !before.Eligibility.Eligible || len(before.Eligibility.Reasons) != 0 {
381			t.Fatalf("earlier eligibility rewritten: %+v", before.Eligibility)
382		}
383	}
