43	// TestRequestViewExpiryScopedToViewedRequest 对应用户给出的主例：实物库存
44	// 十件，甲预留六件并使用两件，乙预留四件，两笔承诺同一时刻到期。到期时刻
45	// 查看甲只确认甲自己：甲 expired、释放四件未用占用、已用两件不回库存；乙
46	// 不被确认。随后以到期前时刻查看，乙仍 active，备件账目为 8/4/4，甲持续
47	// expired。
48	func TestRequestViewExpiryScopedToViewedRequest(t *testing.T) {
49		s := rvSharedStore(t, 10)
