293		v1, err := s.RequestView("r1", before)
294		if err != nil {
295			t.Fatalf("view r1 at earlier time: %v", err)
296		}
297		if d, _ := rvDetail(v1, "c-a1"); d.Status != CommitmentExpired {
298			t.Fatalf("c-a1 rolled back: %+v", d)
299		}
300		if d, _ := rvDetail(v1, "c-b1"); d.Status != CommitmentExpired {
301			t.Fatalf("c-b1 rolled back: %+v", d)
302		}
303		if d, _ := rvDetail(v1, "c-a2"); d.Status != CommitmentActive {
304			t.Fatalf("c-a2 not active at earlier time: %+v", d)
305		}
306	
307		// r2 的承诺到期前仍可正常使用，证明未被 r1 的查询关闭。
308		if _, err := s.Use("u-b2", "c-b2", 1, before); err != nil {
309			t.Fatalf("c-b2 closed by r1 view: %v", err)
310		}
311	}
312	
313	// TestRequestViewFailuresDoNotConfirmExpiry 保障空请求编号返回
314	// ErrInvalidParam、未知请求返回 ErrNotFound，两种失败都不确认任何已有承诺
315	// 到期，也不改变库存；查询资格仍按本次传入时刻计算。
316	func TestRequestViewFailuresDoNotConfirmExpiry(t *testing.T) {
317		s := rvSharedStore(t, 10)
318		noon := t0.Add(10 * day)
319		before := noon.Add(-time.Minute)
320		if _, err := s.Reserve("jia", "r1", "part1", 6, noon, before); err != nil {
321			t.Fatalf("reserve jia: %v", err)
322		}
323		if _, err := s.Use("u-jia", "jia", 2, before); err != nil {
324			t.Fatalf("use jia: %v", err)
325		}
326	
327		// 即便传入晚于到期的时刻，提前失败的查询也不确认任何承诺。
328		if _, err := s.RequestView("", noon); !errors.Is(err, ErrInvalidParam) {
329			t.Fatalf("empty request id: got %v, want ErrInvalidParam", err)
330		}
331		if _, err := s.RequestView("rMissing", noon); !errors.Is(err, ErrNotFound) {
332			t.Fatalf("unknown request: got %v, want ErrNotFound", err)
333		}
334	
335		// 甲未被确认：到期前仍 active、占用四件未用，新使用成功。
336		v, err := s.RequestView("r1", before)
337		if err != nil {
338			t.Fatalf("view r1: %v", err)
339		}
340		d, ok := rvDetail(v, "jia")
341		if !ok || d.Status != CommitmentActive || d.OriginalQuantity != 6 ||
342			d.UsedQuantity != 2 || d.RemainingQuantity != 4 {
343			t.Fatalf("jia after failed views: %+v ok=%v, want active 6/2/4", d, ok)
344		}
345		st, _ := s.PartStatus("part1", before)
346		if st.PhysicalRemaining != 8 || st.ActiveOccupied != 4 || st.Committable != 4 {
347			t.Fatalf("stock changed by failed views: phys=%d occupied=%d committable=%d, want 8/4/4",
348				st.PhysicalRemaining, st.ActiveOccupied, st.Committable)
349		}
350		if c, _ := s.Commitment("jia"); c.Expired {
351			t.Fatalf("jia confirmed by failed view: %+v", c)
352		}
353		if _, err := s.Use("u-jia-more", "jia", 1, before); err != nil {
354			t.Fatalf("jia closed by a non-confirming failed view: %v", err)
355		}
356	}
